import os
from typing import Any, Dict, List, Optional

from azure.cosmos import CosmosClient, PartitionKey, exceptions


class CosmosDocumentStore:
    def __init__(
        self,
        endpoint: Optional[str] = None,
        key: Optional[str] = None,
        database_name: Optional[str] = None,
        container_name: Optional[str] = None,
        partition_key_path: str = "/partitionKey",
    ):
        self.endpoint = endpoint or os.environ.get("AZURE_COSMOS_ENDPOINT")
        self.key = key or os.environ.get("AZURE_COSMOS_KEY")
        self.database_name = database_name or os.environ.get("AZURE_COSMOS_DATABASE", "documents_db")
        self.container_name = container_name or os.environ.get("AZURE_COSMOS_CONTAINER", "documents")
        self.partition_key_path = partition_key_path

        if not self.endpoint or not self.key:
            raise ValueError("AZURE_COSMOS_ENDPOINT and AZURE_COSMOS_KEY must be set or passed explicitly.")

        self.client = CosmosClient(self.endpoint, credential=self.key)
        self.database = self._get_or_create_database()
        self.container = self._get_or_create_container()

    def _get_or_create_database(self):
        try:
            return self.client.create_database_if_not_exists(id=self.database_name)
        except Exception:
            return self.client.get_database_client(self.database_name)

    def _get_or_create_container(self):
        partition_key = PartitionKey(path=self.partition_key_path)
        try:
            return self.database.create_container_if_not_exists(
                id=self.container_name,
                partition_key=partition_key,
                offer_throughput=400,
            )
        except Exception:
            return self.database.get_container_client(self.container_name)

    def upsert_document(self, document: Dict[str, Any]) -> Dict[str, Any]:
        if "id" not in document:
            raise ValueError("Document must contain an 'id' field.")
        if self.partition_key_path.lstrip("/") not in document:
            raise ValueError(f"Document must contain partition key field '{self.partition_key_path.lstrip('/')}'.")
        return self.container.upsert_item(document)

    def get_document(self, doc_id: str, partition_key_value: Any) -> Optional[Dict[str, Any]]:
        try:
            return self.container.read_item(item=doc_id, partition_key=partition_key_value)
        except exceptions.CosmosResourceNotFoundError:
            return None

    def query_by_field(self, field_name: str, field_value: Any, max_items: int = 100) -> List[Dict[str, Any]]:
        query = f"SELECT * FROM c WHERE c.{field_name} = @value"
        params = [{"name": "@value", "value": field_value}]
        items = self.container.query_items(
            query=query,
            parameters=params,
            enable_cross_partition_query=True,
            max_item_count=max_items,
        )
        return list(items)

    def query_by_partition_key(self, partition_key_value: Any, max_items: int = 100) -> List[Dict[str, Any]]:
        query = "SELECT * FROM c WHERE c.partitionKey = @pk"
        params = [{"name": "@pk", "value": partition_key_value}]
        items = self.container.query_items(
            query=query,
            parameters=params,
            partition_key=partition_key_value,
            max_item_count=max_items,
        )
        return list(items)


def query_documents(
    field_name: Optional[str] = None,
    field_value: Optional[Any] = None,
    partition_key_value: Optional[Any] = None,
    endpoint: Optional[str] = None,
    key: Optional[str] = None,
    database_name: Optional[str] = None,
    container_name: Optional[str] = None,
) -> List[Dict[str, Any]]:
    store = CosmosDocumentStore(
        endpoint=endpoint,
        key=key,
        database_name=database_name,
        container_name=container_name,
    )

    if partition_key_value is not None:
        return store.query_by_partition_key(partition_key_value)

    if field_name is None:
        raise ValueError("field_name must be provided when partition_key_value is not used.")
    if field_value is None:
        raise ValueError("field_value must be provided when partition_key_value is not used.")

    return store.query_by_field(field_name, field_value)
